    private void initAdmin() {
        if (accountRepo.findByEmail("systemteacher08@gmail.com").isPresent()) {
            return;
        }

        accountRepo.save(Account.builder().email("systemteacher08@gmail.com").role(Role.ADMIN).firstLogin(true).registerDate(LocalDate.now()).status(Status.ACCOUNT_ACTIVE).isRestricted(false).build());
    }

    private void initParent() {
        if (accountRepo.findByEmail("quynhpvnse182895@fpt.edu.vn").isPresent()) {
            return;
        }

        Account account = accountRepo.save(Account.builder().email("quynhpvnse182895@fpt.edu.vn").role(Role.PARENT).firstLogin(false).registerDate(LocalDate.now()).status(Status.ACCOUNT_ACTIVE).isRestricted(false).build());

        parentRepo.save(Parent.builder().account(account).relationship(Relationship.FATHER).name("John Doe").gender(Gender.MALE).idCardNumber("123456789").workplace("ABC Company").occupation("Engineer").currentAddress("District 1, Ho Chi Minh city").build());
    }

    private void initPrimaryCampusAndCounsellor() {
        School school = resolveOrCreateSeedSchool();

        Account primaryCampusAccount = accountRepo.findByEmail("main-campus@edubridge.local").orElseGet(() -> accountRepo.save(Account.builder().email("main-campus@edubridge.local").role(Role.SCHOOL).firstLogin(true).registerDate(LocalDate.now()).status(Status.ACCOUNT_ACTIVE).isRestricted(false).build()));

        Campus primaryCampus = campusRepo.findBySchoolId(school.getId()).stream().filter(campus -> Boolean.TRUE.equals(campus.getIsPrimaryBranch())).findFirst().orElseGet(() -> campusRepo.save(Campus.builder().school(school).account(primaryCampusAccount).name("Campus Chinh").phoneNumber("0900000000").address("Quan 1, TP Ho Chi Minh").city("Ho Chi Minh").district("Quan 1").latitude(10.7769).longitude(106.7009).boardingType(BoardingType.BOTH).status(Status.VERIFIED).isPrimaryBranch(true).build()));

        primaryCampus = ensurePrimaryCampusSeedFields(primaryCampus, school, primaryCampusAccount);

        Account counsellorAccount = accountRepo.findByEmail("counsellor-main@edubridge.local").orElseGet(() -> accountRepo.save(Account.builder().email("counsellor-main@edubridge.local").role(Role.COUNSELLOR).firstLogin(true).registerDate(LocalDate.now()).status(Status.ACCOUNT_ACTIVE).isRestricted(false).build()));

        Optional<Counsellor> existingCounsellor = counsellorRepo.findByAccountIdAndCampusId(counsellorAccount.getId(), primaryCampus.getId());

        if (existingCounsellor.isPresent()) {
            return;
        }

        counsellorRepo.save(Counsellor.builder().account(counsellorAccount).campus(primaryCampus).name("Counsellor Chinh").employeeCode(UUID.randomUUID()).build());
    }

    private Campus ensurePrimaryCampusSeedFields(Campus campus, School school, Account primaryCampusAccount) {
        boolean changed = false;

        if (campus.getSchool() == null) {
            campus.setSchool(school);
            changed = true;
        }

        if (campus.getAccount() == null) {
            campus.setAccount(primaryCampusAccount);
            changed = true;
        }

        if (campus.getCity() == null) {
            campus.setCity("Ho Chi Minh");
            changed = true;
        }

        if (campus.getDistrict() == null) {
            campus.setDistrict("Quan 1");
            changed = true;
        }

        if (campus.getLatitude() == null) {
            campus.setLatitude(10.7769);
            changed = true;
        }

        if (campus.getLongitude() == null) {
            campus.setLongitude(106.7009);
            changed = true;
        }

        if (campus.getBoardingType() == null) {
            campus.setBoardingType(BoardingType.BOTH);
            changed = true;
        }

        if (changed) {
            return campusRepo.save(campus);
        }

        return campus;
    }

    private School resolveOrCreateSeedSchool() {
        String seedTaxCode = "0312345678";

        return schoolRepo.findAll().stream().filter(school -> seedTaxCode.equals(school.getTaxCode())).findFirst().orElseGet(() -> schoolRepo.save(School.builder().name("EduBridge Seed School").taxCode(seedTaxCode).websiteUrl("https://edubridge.local").hotline("0900000000").averageRating(BigDecimal.ZERO).isFeatured(false).foundingDate(LocalDate.of(2020, 1, 1)).build()));
    }

    private void initConfigSystem() {

        if (platformConfigRepo.count() > 0) {
            return;
        }

        Map<String, Object> businessData = new HashMap<>();
        businessData.put("taxRate", 0.05);
        businessData.put("serviceRate", 0.05);
        businessData.put("minPay", 10000);
        businessData.put("maxPay", 200000000);

        Map<String, Object> mediaData = new HashMap<>();
        mediaData.put("maxImgSize", 10);
        mediaData.put("maxVideoSize", 50);
        mediaData.put("maxDesignRefImg", 4);
        mediaData.put("maxFeedbackImg", 4);
        mediaData.put("maxFeedbackVideo", 1);
        mediaData.put("maxReportImg", 4);
        mediaData.put("maxReportVideo", 1);
        mediaData.put("imgFormat", List.of(Map.of("format", ".jpg"), Map.of("format", ".jpeg"), Map.of("format", ".png"), Map.of("format", ".gif"), Map.of("format", ".webp")));
        mediaData.put("videoFormat", List.of(Map.of("format", ".mp4"), Map.of("format", ".avi"), Map.of("format", ".mov"), Map.of("format", ".wmv"), Map.of("format", ".webm")));

        Map<String, Object> quotaData = new HashMap<>();
        Map<String, Object> year2025 = new HashMap<>();
        year2025.put("sourceUrl", "https://hcm.edu.vn/"); // Link mặc định của Sở
        year2025.put("quotas", new HashMap<String, Integer>()); // Để trống để Admin tự điền sau

        quotaData.put("2025-2026", year2025);

        // --- 4. Subscription Policy (Phần này bạn có dùng trong Request nên nên init luôn) ---
        Map<String, Object> subscriptionData = new HashMap<>();
        subscriptionData.put("trialDays", 30);
        subscriptionData.put("gracePeriod", 7);
        subscriptionData.put("minSubscriptionMonth", 3);

        Map<String, Object> reportData = new HashMap<>();
        reportData.put("maxResolutionDay", 7);
        reportData.put("responseDeadline", LocalDateTime.now().plusHours(4));
        reportData.put("activationDeadline", LocalDateTime.now().plusDays(1));
        reportData.put("bonusDays", 2);
        reportData.put("bonusCondition", "Nếu xử lý quá 24 giờ hoặc lỗi do hệ thống");
        reportData.put("description", "Sau khi báo cáo được xác minh, hệ thống sẽ kích hoạt lại dịch vụ. Nếu xử lý chậm trễ, khách hàng được tặng thêm ngày sử dụng.");
        reportData.put("resolutionLevels", List.of(
                Map.of("name", "High"),
                Map.of("name", "Medium"),
                Map.of("name", "Low")));

        LocalDateTime today = LocalDateTime.now();

        platformConfigRepo.saveAll(List.of(PlatformConfig.builder().key("business").value(businessData)
                        .creationDate(today)
                        .modifiedDate(today)
                        .build(),
                PlatformConfig.builder()
                        .key("media")
                        .value(mediaData)
                        .creationDate(today)
                        .modifiedDate(today)
                        .build(),
                PlatformConfig.builder()
                        .key("quota")
                        .value(quotaData)
                        .creationDate(today)
                        .modifiedDate(today).build(),
                PlatformConfig.builder()
                        .key("subscription")
                        .value(subscriptionData)
                        .creationDate(today)
                        .modifiedDate(today).build(),
                PlatformConfig.builder()
                        .key("report")
                        .value(reportData)
                        .creationDate(today)
                        .modifiedDate(today)
                        .build()));
    }

